//! Reading AEMO's MMS Data Model Report as it is published: a set of HTML
//! pages generated by PowerDesigner, one per package and one per table.
//!
//! The report is the only public source of the Oracle type of every
//! column with its precision and scale, of each table's primary key and of
//! which columns are mandatory. [`fetch_report`] walks it (the list of
//! packages, each package's list of tables, each table's page) and
//! [`to_json`] writes what it found in the shape [`crate::datamodel`]
//! loads, so the committed data-model file can be produced again by
//! anyone, from the source, with one command.
//!
//! The pages are regular enough that no HTML parser is needed: headings
//! are `<h2>` and `<h3>`, every list is a `<table>` of `<tr>` and `<td>`,
//! and nothing nests inside a cell but paragraphs and links.

use std::collections::BTreeMap;

use nemlake_acquire::{FetchError, Fetcher};
use nemlake_core::{Category, Diagnose, Diagnostic};

use crate::datamodel::{DmColumn, DmTable};

/// Where the report's pages live.
pub const REPORT_BASE: &str = "https://visualisations.aemo.com.au/aemo/nemweb/mmsdatamodelreport/electricity/mms%20data%20model%20report_files/";

/// The page that lists the packages and names the model's version.
pub const INDEX_PAGE: &str = "MMS_2.htm";

/// Why the report could not be read.
#[derive(Debug, thiserror::Error)]
pub enum ReportError {
    /// Transport.
    #[error(transparent)]
    Fetch(#[from] FetchError),
    /// A page is not what the report's layout leads to expect.
    #[error("The data-model report page {url} is not {expected}.")]
    Page {
        /// The page.
        url: String,
        /// What it should have been.
        expected: &'static str,
    },
}

impl Diagnose for ReportError {
    fn diagnostic(&self) -> Diagnostic {
        match self {
            Self::Fetch(e) => e.diagnostic(),
            Self::Page { url, expected } => {
                Diagnostic::error("schema.datamodel_page", Category::Schema, self.to_string())
                    .with_url(url.clone())
                    .expected_observed(*expected, "another kind of page")
            }
        }
    }
}

/// A link to another page of the report.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Link {
    /// The text of the link: a package or table name.
    pub name: String,
    /// The page it points at, without the fragment, e.g. `MMS_456.htm`.
    pub page: String,
}

/// What one page of the report is.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Page {
    /// The list of packages.
    Index {
        /// The model the report describes, e.g. `v5.0.0.1`.
        version: Option<String>,
        /// The packages, in report order.
        packages: Vec<Link>,
    },
    /// One package and its tables.
    Package {
        /// Package name.
        name: String,
        /// Its tables, in report order.
        tables: Vec<Link>,
    },
    /// One table. Its `page` and `package` are not on the page itself and
    /// are left empty.
    Table {
        /// Table name.
        name: String,
        /// What the page says of it.
        table: Box<DmTable>,
    },
    /// Anything else.
    Other,
}

/// The text of a fragment of HTML: tags removed, the entities the report
/// uses decoded, runs of white space collapsed to one space. A `<br>` is
/// the only line break the report means, and is kept as one.
pub fn text_of(html: &str) -> String {
    const BREAK: char = '\u{1}';
    let mut raw = String::with_capacity(html.len());
    let mut in_tag = false;
    for (i, c) in html.char_indices() {
        match c {
            '<' => {
                in_tag = true;
                raw.push(if html[i..].starts_with("<br") {
                    BREAK
                } else {
                    ' '
                });
            }
            '>' if in_tag => in_tag = false,
            _ if !in_tag => raw.push(c),
            _ => {}
        }
    }
    let decoded = raw
        .replace("&nbsp;", " ")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&quot;", "\"")
        .replace("&#39;", "'")
        .replace("&amp;", "&");
    let lines: Vec<String> = decoded
        .split(BREAK)
        .map(|line| line.split_whitespace().collect::<Vec<_>>().join(" "))
        .collect();
    lines.join("\n").trim().to_owned()
}

/// One heading of a page with the HTML up to the next heading.
struct Section<'a> {
    level: u8,
    title: String,
    body: &'a str,
}

fn sections(html: &str) -> Vec<Section<'_>> {
    let mut starts: Vec<(usize, u8)> = Vec::new();
    for (tag, level) in [("<h2>", 2u8), ("<h3>", 3u8)] {
        starts.extend(html.match_indices(tag).map(|(i, _)| (i, level)));
    }
    starts.sort_unstable();
    let mut out = Vec::with_capacity(starts.len());
    for (n, &(at, level)) in starts.iter().enumerate() {
        let end = starts.get(n + 1).map_or(html.len(), |&(next, _)| next);
        let whole = &html[at..end];
        let close = if level == 2 { "</h2>" } else { "</h3>" };
        let (title, body) = match whole.find(close) {
            Some(i) => (&whole[4..i], &whole[i + close.len()..]),
            None => (&whole[4..], ""),
        };
        out.push(Section {
            level,
            title: text_of(title),
            body,
        });
    }
    out
}

/// One cell of a table: its text and the page its first link points at.
struct Cell {
    text: String,
    page: Option<String>,
}

/// The rows of the first table in `body`. The navigation at the foot of
/// each page comes after a rule and is left out.
fn rows(body: &str) -> Vec<Vec<Cell>> {
    let body = body.split("<hr").next().unwrap_or(body);
    let table = match (body.find("<table"), body.find("</table>")) {
        (Some(a), Some(b)) if a < b => &body[a..b],
        _ => return Vec::new(),
    };
    table
        .split("<tr")
        .skip(1)
        .map(|row| {
            row.split("<td")
                .skip(1)
                .map(|cell| {
                    // What follows the cell's own tag, up to its end.
                    let inner = cell.split_once('>').map_or("", |(_, rest)| rest);
                    let inner = inner.split("</td>").next().unwrap_or(inner);
                    let page = inner.split_once("href=\"").and_then(|(_, rest)| {
                        let href = rest.split('"').next()?;
                        let page = href.split('#').next()?;
                        (!page.is_empty()).then(|| page.to_owned())
                    });
                    Cell {
                        text: text_of(inner),
                        page,
                    }
                })
                .collect()
        })
        .collect()
}

/// The rows of a grid after its header row.
fn grid(body: &str) -> Vec<Vec<Cell>> {
    rows(body).into_iter().skip(1).collect()
}

fn links(body: &str) -> Vec<Link> {
    grid(body)
        .into_iter()
        .filter_map(|row| {
            let first = row.into_iter().next()?;
            Some(Link {
                page: first.page?,
                name: first.text,
            })
        })
        .collect()
}

/// Reads one page of the report.
pub fn parse_page(html: &str) -> Page {
    let sections = sections(html);
    let Some(first) = sections.first() else {
        return Page::Other;
    };
    let section = |title: &str| sections.iter().find(|s| s.title == title);
    if let Some(name) = first.title.strip_prefix("Package: ") {
        return Page::Package {
            name: name.to_owned(),
            tables: section("List of tables").map_or_else(Vec::new, |s| links(s.body)),
        };
    }
    if let Some(name) = first.title.strip_prefix("Table: ") {
        // The form under the first heading: name and comment.
        let description = sections
            .get(1)
            .filter(|s| s.level == 3)
            .and_then(|s| {
                rows(s.body)
                    .into_iter()
                    .find(|r| r.first().is_some_and(|c| c.text == "Comment"))
            })
            .and_then(|r| r.into_iter().nth(1))
            .map(|c| c.text)
            .filter(|t| !t.is_empty());
        let visibility = section("Notes").and_then(|s| {
            grid(s.body)
                .into_iter()
                .find(|r| r.first().is_some_and(|c| c.text == "Visibility"))
                .and_then(|r| r.into_iter().nth(2))
                .map(|c| c.text)
                .filter(|t| !t.is_empty())
        });
        // A page may have several lists under one title. Of the lists
        // headed "Primary Key Columns" the first is the primary key and
        // any other a further unique key, which is not recorded; the
        // lists headed "Index Columns" are one index each.
        let names = |title: &str, lists: usize| -> Vec<String> {
            let mut out: Vec<String> = Vec::new();
            for s in sections.iter().filter(|s| s.title == title).take(lists) {
                for row in grid(s.body) {
                    if let Some(c) = row.into_iter().next()
                        && !c.text.is_empty()
                        && !out.contains(&c.text)
                    {
                        out.push(c.text);
                    }
                }
            }
            out
        };
        let columns = section("Content").map_or_else(Vec::new, |s| {
            grid(s.body)
                .into_iter()
                .filter_map(|row| {
                    let mut cells = row.into_iter();
                    let name = cells.next()?.text;
                    let oracle = cells.next()?.text;
                    let mandatory = cells.next().is_some_and(|c| c.text == "X");
                    let comment = cells.next().map(|c| c.text).unwrap_or_default();
                    (!name.is_empty()).then_some(DmColumn {
                        name,
                        oracle,
                        mandatory,
                        comment,
                    })
                })
                .collect()
        });
        return Page::Table {
            // The report writes two table names with a space inside
            // (`SET_ APC_RECOVERY`); an Oracle name has none.
            name: name.split_whitespace().collect(),
            table: Box::new(DmTable {
                page: String::new(),
                package: String::new(),
                description,
                visibility,
                primary_key: names("Primary Key Columns", 1),
                indexes: names("Index Columns", usize::MAX),
                columns,
            }),
        };
    }
    if let Some(list) = section("List of packages") {
        let version = sections
            .iter()
            .find_map(|s| s.title.strip_prefix("Description of the model "))
            .and_then(|model| {
                model.split_whitespace().find(|w| {
                    w.starts_with('v') && w[1..].starts_with(|c: char| c.is_ascii_digit())
                })
            })
            .map(str::to_owned);
        return Page::Index {
            version,
            packages: links(list.body),
        };
    }
    Page::Other
}

/// The whole report.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Report {
    /// The model's version, e.g. `v5.0.0.1`.
    pub version: Option<String>,
    /// Tables by name.
    pub tables: BTreeMap<String, DmTable>,
}

/// How long a fetched page is reused from the cache: the report changes
/// with a data-model release, a few times a year.
const PAGE_TTL: i64 = 7 * 86_400;

async fn page(fetcher: &Fetcher, base: &str, name: &str) -> Result<(String, Page), ReportError> {
    let url = format!("{base}{name}");
    let body = fetcher.fetch_listing(&url, PAGE_TTL).await?;
    let parsed = parse_page(&String::from_utf8_lossy(&body));
    Ok((url, parsed))
}

/// Walks the report at `base` (see [`REPORT_BASE`]): one request for the
/// list of packages, one per package, one per table, each through the
/// fetcher and so paced and cached.
pub async fn fetch_report(fetcher: &Fetcher, base: &str) -> Result<Report, ReportError> {
    let (url, index) = page(fetcher, base, INDEX_PAGE).await?;
    let Page::Index { version, packages } = index else {
        return Err(ReportError::Page {
            url,
            expected: "the list of packages",
        });
    };
    let mut report = Report {
        version,
        tables: BTreeMap::new(),
    };
    for package in &packages {
        let (url, parsed) = page(fetcher, base, &package.page).await?;
        let Page::Package { name, tables } = parsed else {
            return Err(ReportError::Page {
                url,
                expected: "a package",
            });
        };
        for link in &tables {
            let (url, parsed) = page(fetcher, base, &link.page).await?;
            let Page::Table {
                name: table,
                table: mut def,
            } = parsed
            else {
                return Err(ReportError::Page {
                    url,
                    expected: "a table",
                });
            };
            def.page.clone_from(&link.page);
            def.package.clone_from(&name);
            report.tables.insert(table.to_ascii_uppercase(), *def);
        }
    }
    Ok(report)
}

/// The report as the JSON [`crate::datamodel::DataModel::load`] reads: one
/// object keyed by table name, keys in order, so the same report always
/// gives the same bytes.
pub fn to_json(report: &Report) -> String {
    let mut text = serde_json::to_string_pretty(&report.tables)
        .expect("a map of strings and lists serialises");
    text.push('\n');
    text
}

#[cfg(test)]
mod tests {
    use std::sync::Arc;
    use std::time::Duration;

    use nemlake_acquire::transport::{Canned, StaticTransport};
    use nemlake_acquire::{DiskCache, FetcherConfig};

    use super::*;

    fn fixture(name: &str) -> String {
        let p = format!(
            "{}/../../testdata/bootstrap/datamodel/pages/{name}",
            env!("CARGO_MANIFEST_DIR")
        );
        std::fs::read_to_string(p).unwrap()
    }

    #[test]
    fn strips_markup() {
        assert_eq!(
            text_of("<p align=\"left\">A &amp; B&nbsp;\n &lt;x&gt; &quot;q&quot; &#39;s&#39;</p>"),
            "A & B <x> \"q\" 's'"
        );
        assert_eq!(text_of("a > b"), "a > b");
        assert_eq!(
            text_of("<p>One of:<br />\r\n* 1 = on<br />\r\n* 0 = off\r\n</p>"),
            "One of:\n* 1 = on\n* 0 = off"
        );
        assert_eq!(text_of("<br /> x <br />"), "x");
        assert_eq!(text_of(""), "");
    }

    #[test]
    fn reads_the_index() {
        let Page::Index { version, packages } = parse_page(&fixture("MMS_2.htm")) else {
            panic!("not an index");
        };
        assert_eq!(version.as_deref(), Some("v5.0.0.1"));
        assert_eq!(packages.len(), 31);
        assert_eq!(
            packages[0],
            Link {
                name: "CONFIGURATION".into(),
                page: "MMS_3.htm".into()
            }
        );
        assert!(
            packages
                .iter()
                .any(|p| p.name == "MCC_DISPATCH" && p.page == "MMS_455.htm")
        );
    }

    #[test]
    fn reads_a_package_and_a_table() {
        let Page::Package { name, tables } = parse_page(&fixture("MMS_455.htm")) else {
            panic!("not a package");
        };
        assert_eq!(name, "MCC_DISPATCH");
        assert_eq!(
            tables,
            [
                Link {
                    name: "MCC_CASESOLUTION".into(),
                    page: "MMS_456.htm".into()
                },
                Link {
                    name: "MCC_CONSTRAINTSOLUTION".into(),
                    page: "MMS_457.htm".into()
                }
            ]
        );
        let Page::Table { name, table } = parse_page(&fixture("MMS_457.htm")) else {
            panic!("not a table");
        };
        assert_eq!(name, "MCC_CONSTRAINTSOLUTION");
        assert!(
            table
                .description
                .as_deref()
                .unwrap()
                .starts_with("Constraint solution data")
        );
        assert_eq!(
            table.visibility.as_deref(),
            Some("Private; Public Next-Day")
        );
        assert_eq!(table.primary_key, ["CONSTRAINTID", "RUN_DATETIME"]);
        assert_eq!(
            table
                .columns
                .iter()
                .map(|c| (c.name.as_str(), c.oracle.as_str(), c.mandatory))
                .collect::<Vec<_>>(),
            [
                ("RUN_DATETIME", "DATE", true),
                ("CONSTRAINTID", "VARCHAR2(20)", true),
                ("RHS", "NUMBER(15,5)", false),
                ("MARGINALVALUE", "NUMBER(15,5)", false),
            ]
        );
        assert!(!table.columns[2].comment.is_empty());
    }

    #[test]
    fn other_pages_are_neither() {
        assert_eq!(parse_page("<html><body>nothing</body></html>"), Page::Other);
        assert_eq!(parse_page("<h3>Something else</h3><p>x</p>"), Page::Other);
        // A heading that never closes and a table that never opens.
        let Page::Package { tables, .. } = parse_page("<h2>Package: P</h2><h3>List of tables")
        else {
            panic!("not a package");
        };
        assert!(tables.is_empty());
        let Page::Table { table, .. } = parse_page("<h2>Table: T</h2>") else {
            panic!("not a table");
        };
        assert!(table.columns.is_empty() && table.description.is_none());
        // Two key lists: the first is the primary key. Two index lists:
        // both are indexes. A space inside a table name is a slip.
        let list = |title: &str, name: &str| {
            format!("<h3>{title}</h3><table><tr><td>Name</td></tr><tr><td>{name}</td></tr></table>")
        };
        let html = format!(
            "<h2>Table: SET_ X</h2>{}{}{}{}",
            list("Primary Key Columns", "FILENAME"),
            list("Primary Key Columns", "OFFERDATE"),
            list("Index Columns", "LASTCHANGED"),
            list("Index Columns", "PARTICIPANTID")
        );
        let Page::Table { name, table } = parse_page(&html) else {
            panic!("not a table");
        };
        assert_eq!(name, "SET_X");
        assert_eq!(table.primary_key, ["FILENAME"]);
        assert_eq!(table.indexes, ["LASTCHANGED", "PARTICIPANTID"]);
        let Page::Index { version, packages } = parse_page("<h3>List of packages</h3>") else {
            panic!("not an index");
        };
        assert!(version.is_none() && packages.is_empty());
    }

    fn fetcher(t: &Arc<StaticTransport>, dir: &std::path::Path) -> Fetcher {
        Fetcher::new(
            Arc::new(t.clone()),
            DiskCache::new(dir),
            FetcherConfig {
                attempts: 1,
                min_interval: Duration::ZERO,
                ..Default::default()
            },
        )
    }

    /// A report of one package: the index, the package and its two tables
    /// are fetched, and the JSON is what the data-model loader reads.
    #[tokio::test]
    async fn walks_a_report_and_writes_the_loaders_json() {
        let base = "https://r/files/";
        let one_package = "<h3>List of packages</h3><table><tr><td>Name</td></tr>\
            <tr><td><p><a href=\"MMS_455.htm#1\">MCC_DISPATCH</a></p></td></tr></table>\
            <h3>Description of the model MMS Data Model v9.9 Oracle</h3>";
        let t = Arc::new(StaticTransport::default());
        t.add(
            &format!("{base}MMS_2.htm"),
            Canned::ok(one_package.as_bytes()),
        );
        for p in ["MMS_455.htm", "MMS_456.htm", "MMS_457.htm"] {
            t.add(&format!("{base}{p}"), Canned::ok(fixture(p).as_bytes()));
        }
        let dir = tempfile::tempdir().unwrap();
        let report = fetch_report(&fetcher(&t, dir.path()), base).await.unwrap();
        assert_eq!(report.version.as_deref(), Some("v9.9"));
        assert_eq!(
            report.tables.keys().collect::<Vec<_>>(),
            ["MCC_CASESOLUTION", "MCC_CONSTRAINTSOLUTION"]
        );
        let table = &report.tables["MCC_CONSTRAINTSOLUTION"];
        assert_eq!(
            (table.page.as_str(), table.package.as_str()),
            ("MMS_457.htm", "MCC_DISPATCH")
        );

        let json = to_json(&report);
        assert!(json.ends_with("}\n"));
        let path = dir.path().join("dm.json");
        std::fs::write(&path, &json).unwrap();
        let dm = crate::datamodel::DataModel::load(&path).unwrap();
        assert_eq!(dm.tables.len(), 2);
        assert_eq!(dm.table("mcc_constraintsolution").unwrap(), table);
        assert_eq!(
            to_json(&report),
            json,
            "the same report gives the same bytes"
        );
    }

    /// A page that is not what the walk expects stops it and says which.
    #[tokio::test]
    async fn a_page_of_the_wrong_kind_is_an_error() {
        let base = "https://r/files/";
        let dir = tempfile::tempdir().unwrap();
        let expect = |t: Arc<StaticTransport>, what: &'static str| {
            let dir = dir.path().join(what.replace(' ', "_"));
            async move {
                let e = fetch_report(&fetcher(&t, &dir), base).await.unwrap_err();
                let d = e.diagnostic();
                assert_eq!(d.code, "schema.datamodel_page");
                assert!(e.to_string().contains(what), "{e}");
            }
        };
        let t = Arc::new(StaticTransport::default());
        t.add(&format!("{base}MMS_2.htm"), Canned::ok(b"<html></html>"));
        expect(t, "the list of packages").await;

        let index = "<h3>List of packages</h3><table><tr><td>Name</td></tr>\
            <tr><td><a href=\"MMS_455.htm#1\">P</a></td></tr></table>";
        let t = Arc::new(StaticTransport::default());
        t.add(&format!("{base}MMS_2.htm"), Canned::ok(index.as_bytes()));
        t.add(&format!("{base}MMS_455.htm"), Canned::ok(b"<h3>x</h3>"));
        expect(t, "a package").await;

        let t = Arc::new(StaticTransport::default());
        t.add(&format!("{base}MMS_2.htm"), Canned::ok(index.as_bytes()));
        t.add(
            &format!("{base}MMS_455.htm"),
            Canned::ok(fixture("MMS_455.htm").as_bytes()),
        );
        t.add(&format!("{base}MMS_456.htm"), Canned::ok(b"<h3>x</h3>"));
        expect(t, "a table").await;

        // A page that cannot be fetched is the fetcher's error.
        let t = Arc::new(StaticTransport::default());
        t.add(&format!("{base}MMS_2.htm"), Canned::status(404));
        let e = fetch_report(&fetcher(&t, &dir.path().join("gone")), base)
            .await
            .unwrap_err();
        assert!(
            e.diagnostic().code.starts_with("net."),
            "{}",
            e.diagnostic().code
        );
    }
}
